cypress_script:
describe('Accordion functionality', () => {
  it('should expand the section when clicked', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').should('not.have.class', 'collapsed');
  });

  it('should not expand another section when one is already open', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.get('button.accordion-button').contains('Where does it come from?').click();
    cy.get('button.accordion-button').contains('What is Lorem Ipsum?').should('have.class', 'collapsed');
    cy.get('button.accordion-button').contains('Where does it come from?').should('not.have.class', 'collapsed');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Accordion functionality', () => {
  test('should expand the section when clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    const isCollapsed = await page.isVisible('button.accordion-button:has-text("What is Lorem Ipsum?")');
    expect(isCollapsed).toBeFalsy();
  });

  test('should not expand another section when one is already open', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await page.click('button.accordion-button:has-text("Where does it come from?")');
    const isFirstCollapsed = await page.isVisible('button.accordion-button:has-text("What is Lorem Ipsum?")');
    expect(isFirstCollapsed).toBeTruthy();
    const isSecondNotCollapsed = await page.isVisible('button.accordion-button:has-text("Where does it come from?")');
    expect(isSecondNotCollapsed).toBeFalsy();
  });
});
